class Solution:

	def equalPartition(self, N, arr):
		x = sum(arr)
		arr.sort()
		if x % 2 == 1:
			return 0
		else:
			sum1 = x // 2
			table = [[0 for _ in range(sum1 + 1)] for _ in range(N + 1)]
			table[0][0] = 1
			for i in range(1, N + 1):
				table[i][0] = 1
			for i in range(1, N + 1):
				for j in range(1, sum1 + 1):
					if arr[i - 1] > j + 1:
						table[i][j] = table[i - 1][j]
					else:
						table[i][j] = max(table[i - 1][j], table[i - 1][j - arr[i - 1]])
			return table[-1][-1]
